假设程序运行在 x86-64 小端机器上，编译器按照标准规则对齐，并且有 NaN 参与的算术比较均返回 0。请根据 C 程序与右侧汇编所反映的操作，填写四处缺失的 C 表达式。

```c
struct a {
    char c[2][3];
    int i;
};

struct b {
    float f;
    struct a a;
    char c;
};

union c {
    struct a a;
    struct b b;
    struct b *pb;
};

void proc1(union c *u) {
    double a = u->b.f {{blank:proc1-a}};
    double b = u->b.f {{blank:proc1-b}};
    printf("%d\n", a == b);
}

void proc2(union c *u) {
    char *a = u->a.c[1] + 1;
    char *b = (u->a.c + 1)[1];
    printf("%d\n", (int)(b - a));
}

void proc3(union c *u) {
    char x = u->a.c[1][0];
    char y = {{blank:proc3-y}};
    if (x == 0x7F && (y & 0x80) == 0x80) {
        printf("%d\n", u->b.f < u->a.i);
    } else {
        printf("0\n");
    }
}

void proc4(union c *u) {
    int x = u->a.i;
    int y = {{blank:proc4-y}};
    printf("%d\n", (x > y) != (-x < -y));
}

int main(void) {
    printf("%zu\n", sizeof(struct a));
    printf("%zu\n", sizeof(struct b));
    printf("%zu\n", sizeof(union c));

    union c u;
    /* 随机初始化 u */
    proc1(&u);
    proc2(&u);
    proc3(&u);
    proc4(&u);
}
```

与四个空相关的汇编片段如下：

```asm
# proc1：第一条路径先做单精度加法，第二条路径先扩展为双精度
movss      (%rcx), %xmm1
movss      .LC0(%rip), %xmm0
addss      %xmm1, %xmm0
cvtss2sd   %xmm0, %xmm2

movss      (%rcx), %xmm0
cvtss2sd   %xmm0, %xmm0
